arguments.command:
python3 -c '
import ezdxf

base = "/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind"

doc = ezdxf.readfile(base + "/project/10_drawings/structural/S-201_Roof_Framing_Plan_RevC.dxf")
for e in doc.modelspace():
    if e.dxftype() in ("TEXT", "MTEXT") and e.dxf.insert.y > 190:
        print("S-201 note:", e.dxf.text)
    elif e.dxf.layer in ("S-DECK-ZONE", "S-CHORD", "S-COLL"):
        if e.dxftype() == "LINE":
            print(f"  {e.dxf.layer} LINE ({e.dxf.start.x:.1f},{e.dxf.start.y:.1f})->({e.dxf.end.x:.1f},{e.dxf.end.y:.1f})")
        elif e.dxftype() == "LWPOLYLINE":
            pts = [(p[0], p[1]) for p in e.get_points()]
            print(f"  {e.dxf.layer} POLY {pts}")

doc_a1 = ezdxf.readfile(base + "/project/10_drawings/architectural/A-101_Roof_Plan_RevC.dxf")
for e in doc_a1.modelspace():
    if e.dxf.layer in ("A-WALL", "A-OPEN") and e.dxftype() == "LWPOLYLINE":
        print(f"A-101 {e.dxf.layer} POLY {[(p[0], p[1]) for p in e.get_points()]}")

doc_a3 = ezdxf.readfile(base + "/project/10_drawings/architectural/A-301_Exterior_Elevations_RevC.dxf")
for e in doc_a3.modelspace():
    if e.dxftype() in ("TEXT", "MTEXT"):
        print("A-301:", e.dxf.text)
'

