            ps.update({p.Name: p.NominalValue.wrappedValue for p in rel.RelatingPropertyDefinition.HasProperties})
    v_list = []
    for v in getattr(w, "HasOpenings", []):
        oe = v.RelatedOpeningElement
        ops = {}
        for rel in oe.IsDefinedBy:
            if rel.is_a("IfcRelDefinesByProperties") and rel.RelatingPropertyDefinition.is_a("IfcPropertySet"):
                ops.update({p.Name: p.NominalValue.wrappedValue for p in rel.RelatingPropertyDefinition.HasProperties})
